code.C:
#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int odd = 0, even = 0;
    for (int i = 0; i < n; i++) {
        long long x; scanf("%lld", &x);
        if (x % 2 != 0) odd++; else even++;
    }
    printf("%d %d\n", odd, even);
    return 0;
}

