code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int odd = 0, even = 0;
            for (int i = 0; i < n; i++) {
                long x = sc.nextLong();
                if (x % 2 != 0) odd++; else even++;
            }
            System.out.println(odd + " " + even);
        }
    }
}

