const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    let odd = 0, even = 0;
    for (let i = 1; i <= n; i++) {
        if (BigInt(toks[i]) % 2n !== 0n) odd++; else even++;
    }
    console.log(`${odd} ${even}`);
}
main();

